"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re
import sys


STAMP = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = frozenset(("DONE", "BLOCKED", "NEEDS-USER", "FAILED"))
REQUIRED = ("id", "from", "to", "status", "at")


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None or at.utcoffset() is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not STAMP.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return (fields, at), None


def summarize(root, now):
    boxes = {}
    paths = []
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, folder in (("inbox", inbox), ("done", inbox / "done")):
            if folder.is_symlink() or not folder.is_dir():
                continue
            for path in folder.iterdir():
                if (path.name.startswith(".") or path.suffix != ".md"
                        or path.is_symlink() or not path.is_file()):
                    continue
                paths.append((path.relative_to(root).as_posix(), path, box.name, where))

    seen = set()
    requests = []
    resolved = set()
    bad = []
    for relative, path, box, where in sorted(paths):
        letter, why = read_letter(path, now)
        if why is None and letter[0]["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        fields, at = letter
        seen.add(fields["id"])
        if where == "inbox":
            counts = boxes[box]["inbox"]
            status = fields["status"]
            counts[status] = counts.get(status, 0) + 1
        else:
            boxes[box]["done"] += 1
        if fields["status"] == "REQUEST":
            requests.append((fields, at, where))
        if fields["status"] in RESOLVING and fields.get("re"):
            resolved.add(fields["re"])

    opened = [{"id": fields["id"], "from": fields["from"],
               "to": fields["to"], "where": where,
               "age_min": (now - at) // timedelta(minutes=1)}
              for fields, at, where in requests if fields["id"] not in resolved]
    for value in boxes.values():
        value["inbox"] = dict(sorted(value["inbox"].items()))
    return {"v": 1, "open": sorted(opened, key=lambda item: (item["to"], item["id"])),
            "boxes": boxes, "bad": sorted(bad, key=lambda item: (item["file"], item["why"]))}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
